const DEMO={"id": "basics", "title": "Fingerstyle Guitar (demo)", "sub": "Thumb and fingers, Travis picking and a first piece", "drums": {"met": {"hh": "x...x...x...x...", "sn": "................", "bd": "K..............."}, "soft": {"hh": "x...x...x...x...", "sn": "................", "bd": "K.......K......."}, "bal": {"hh": "x.x.x.x.x.x.x.x.", "sn": "....c.......c...", "bd": "K.......K......."}, "wz": {"hh": "x...x...x...", "sn": "....c...c...", "bd": "K..........."}, "trn": {"hh": "xxxxxxxxxxxxxxxx", "sn": "....c.......c...", "bd": "K.......K......."}}, "tone": "steel", "demo": true, "levels": [{"n": 1, "sections": [{"title": "FIRST STEPS: THUMB AND FINGERS", "patterns": [{"t": "Thumb and index", "bpm": 66, "tip": "p on the root, then i on the 3rd string, one per beat. Free stroke on i. Keep the chord held the whole bar so both notes ring.", "ch": "Em | Am | C | G", "gtr": "s---g---s---g---|f---g---f---g---|f---g---f---g---|s---g---s---g---", "key": "G", "dr": "soft", "leg": {"s": "@6", "f": "@5", "d": "@4", "g": "@3", "b": "@2", "e": "@1", "x": "@61", "y": "@51", "z": "@41", "k": "@321"}, "tone": "steel", "pf": {"gt": "p...i...p...i...|p...i...p...i...|p...i...p...i...|p...i...p...i..."}, "inst": "fs", "num": "1.8"}, {"t": "p i m a on Em and Am", "bpm": 66, "tip": "p, i, m, a twice per bar. Both chords use the open 1st string at the top; only the thumb changes string, from the 6th to the 5th.", "ch": "Em | Am | Em | Am", "gtr": "s-g-b-e-s-g-b-e-|f-g-b-e-f-g-b-e-|s-g-b-e-s-g-b-e-|f-g-b-e-f-g-b-e-", "key": "G", "dr": "bal", "leg": {"s": "@6", "f": "@5", "d": "@4", "g": "@3", "b": "@2", "e": "@1", "x": "@61", "y": "@51", "z": "@41", "k": "@321"}, "tone": "nylon", "pf": {"gt": "p.i.m.a.p.i.m.a.|p.i.m.a.p.i.m.a.|p.i.m.a.p.i.m.a.|p.i.m.a.p.i.m.a."}, "inst": "fs", "num": "1.12"}]}, {"title": "TRAVIS PICKING", "patterns": [{"t": "Thumb on C", "bpm": 63, "tip": "p only: 5th string (C), 4th (E), 6th (G), 4th (E). The ring finger hops from the 5th to the 6th string for beat 3 and back for beat 1.", "ch": "C/G | C/G", "gtr": "f---d---s---d---|f---d---s---d---", "key": "C", "pf": {"gt": "p...p...p...p...|p...p...p...p..."}, "leg": {"s": "@6", "f": "@5", "d": "@4", "g": "@3", "b": "@2", "e": "@1", "w": "@61", "y": "@51", "z": "@41", "k": "@21"}, "dr": "soft", "inst": "fs", "num": "3.1"}, {"t": "Every \"and\"", "bpm": 66, "tip": "i on the B string after every thumb note: thumb-and, thumb-and. Say it out loud; the thumb is on the numbers, the finger on \"and\".", "ch": "C/G | C/G | G | G", "gtr": "f-b-d-b-s-b-d-b-|f-b-d-b-s-b-d-b-|s-b-d-b-s-b-d-b-|s-b-d-b-s-b-d-b-", "key": "C", "pf": {"gt": "p.i.p.i.p.i.p.i.|p.i.p.i.p.i.p.i.|p.i.p.i.p.i.p.i.|p.i.p.i.p.i.p.i."}, "leg": {"s": "@6", "f": "@5", "d": "@4", "g": "@3", "b": "@2", "e": "@1", "w": "@61", "y": "@51", "z": "@41", "k": "@21"}, "dr": "bal", "inst": "fs", "num": "3.5"}, {"t": "The standard pattern", "bpm": 66, "tip": "Pinch (p + m), thumb, i, thumb, m, thumb, i. The m on the \"and\" of 3 is the new note; listen for the little skip it gives the bar.", "ch": "C/G | C/G", "gtr": "y---d-b-s-e-d-b-|y---d-b-s-e-d-b-", "key": "C", "pf": {"gt": "p...p.i.p.m.p.i.|p...p.i.p.m.p.i."}, "leg": {"s": "@6", "f": "@5", "d": "@4", "g": "@3", "b": "@2", "e": "@1", "w": "@61", "y": "@51", "z": "@41", "k": "@21"}, "dr": "soft", "inst": "fs", "num": "3.9"}, {"t": "Standard pattern, four chords", "bpm": 76, "tip": "C, Am, C and G7: the right hand does the same thing in every bar; only the thumb string on beat 1 changes. G7 puts F on top.", "ch": "C/G | Am | C/G | G7", "gtr": "y---d-b-s-e-d-b-|y---d-b-f-e-d-b-|y---d-b-s-e-d-b-|w---d-b-s-e-d-b-", "key": "C", "leg": {"s": "@6", "f": "@5", "d": "@4", "g": "@3", "b": "@2", "e": "@1", "w": "@61", "y": "@51", "z": "@41", "k": "@21"}, "dr": "bal", "inst": "fs", "num": "3.10"}]}, {"title": "A FIRST PIECE", "patterns": [{"t": "Front Porch Morning", "bpm": 72, "tip": "A: the up-and-back arpeggio, softly. B: a pinch on every beat 1, a little louder. In the last bar the thumb, i, m and a climb the Em chord once more and end on a pinch that rings.", "ch": "Em | C | G | D | Em | Am | D | Em", "gtr": "s-g-b-e-b-g-b-g-|f-g-b-e-b-g-b-g-|s-g-b-e-b-g-b-g-|d-g-b-e-b-g-b-g-|x-g-b-g-s-g-b-g-|y-g-b-g-f-g-b-g-|z-g-b-g-d-g-b-g-|s-g-b-e-x-------", "key": "G", "dr": "bal", "leg": {"s": "@6", "f": "@5", "d": "@4", "g": "@3", "b": "@2", "e": "@1", "x": "@61", "y": "@51", "z": "@41", "k": "@321"}, "tone": "steel", "lbl": {"0": "A", "4": "B"}, "dyn": "0:mp 64:mf 112:>", "pf": {"gt": "p.i.m.a.m.i.m.i.|p.i.m.a.m.i.m.i.|p.i.m.a.m.i.m.i.|p.i.m.a.m.i.m.i.|p.i.m.i.p.i.m.i.|p.i.m.i.p.i.m.i.|p.i.m.i.p.i.m.i.|p.i.m.a.p......."}, "inst": "fs", "num": "1.21"}]}]}]};